INSERT INTO categories (id, name, slug, description, image_url, created_at) VALUES
  ('7a83a44e-7ea9-588d-90a9-c6f30b1ed62f', 'Audio', 'audio', 'Headphones, earbuds and speakers tuned for everyday listening and critical work.', 'https://loremflickr.com/800/600/headphones,audio?lock=87', TIMESTAMP '2026-01-02 09:00:00'),
  ('06610ee3-a46b-5738-adfd-4ae2b5814604', 'Computing', 'computing', 'Laptops, displays, storage and the peripherals that surround them.', 'https://loremflickr.com/800/600/laptop,computer?lock=415', TIMESTAMP '2026-01-02 09:00:00'),
  ('4cdd788c-eb64-5767-b65f-9606f83b2bcb', 'Mobile & Tablets', 'mobile-tablets', 'Phones, tablets and the accessories that keep them running.', 'https://loremflickr.com/800/600/smartphone,tablet?lock=549', TIMESTAMP '2026-01-02 09:00:00'),
  ('9d51aa3b-8168-5cd8-a37c-8df2604fe561', 'Wearables', 'wearables', 'Smartwatches and fitness trackers built for all-day wear.', 'https://loremflickr.com/800/600/smartwatch,wearable?lock=827', TIMESTAMP '2026-01-02 09:00:00'),
  ('1b5a23ae-8705-55c1-a9a3-537afe033713', 'Home & Kitchen', 'home-kitchen', 'Considered appliances for the kitchen counter and the living room.', 'https://loremflickr.com/800/600/kitchen,appliance?lock=386', TIMESTAMP '2026-01-02 09:00:00'),
  ('1a79b9fd-2436-5f30-8f4c-de6d3d65b383', 'Photography', 'photography', 'Cameras and lenses for people who shoot deliberately.', 'https://loremflickr.com/800/600/camera,photography?lock=757', TIMESTAMP '2026-01-02 09:00:00'),
  ('8740d7f6-b451-5b59-b10b-124aa0e8a53d', 'Gaming', 'gaming', 'Controllers, headsets and gear for long sessions.', 'https://loremflickr.com/800/600/gaming,controller?lock=452', TIMESTAMP '2026-01-02 09:00:00');
