INSERT INTO products (id, sku, slug, name, short_description, description, price, compare_at_price, currency, category_id, brand_id, image_url, rating_average, rating_count, featured, active, created_at, updated_at) VALUES
  ('343213de-c447-56c6-ac74-dd29fcff1fec', 'AUR-HALO-BLK', 'aurelia-halo-noise-cancelling-headphones', 'Aurelia Halo Noise-Cancelling Headphones', 'Over-ear ANC headphones with 40-hour battery and memory-foam cushions.', 'The Halo pairs a two-stage adaptive noise-cancelling system with 40mm bio-cellulose drivers, so commuter rumble disappears without the hollow, pressurised feeling that cheaper cancellation produces. Memory-foam earcups sit flat against the head for long sessions, and the folding yoke means it packs down into a bag rather than dominating one. A single charge runs for forty hours with cancellation active.', 18999.00, 24999.00, 'INR', '7a83a44e-7ea9-588d-90a9-c6f30b1ed62f', '417365a8-31ea-5bc6-b24b-84b8ad8f9bfc', 'https://loremflickr.com/900/900/headphones?lock=310', 4.70, 2143, TRUE, TRUE, TIMESTAMP '2026-01-03 10:21:00', TIMESTAMP '2026-01-03 10:21:00'),
  ('06e48299-d406-5f29-bcee-728d902d65ea', 'AUR-DRIFT-WHT', 'aurelia-drift-wireless-earbuds', 'Aurelia Drift Wireless Earbuds', 'Compact true-wireless earbuds with a pocketable charging case.', 'Drift is built around comfort over commotion: a 5.4mm driver in a shell light enough to forget, tuned slightly warm so podcasts and calls stay easy on the ear. The case adds three full charges and closes with a magnet you can find without looking. IPX5 means rain and sweat are non-events.', 6499.00, 8999.00, 'INR', '7a83a44e-7ea9-588d-90a9-c6f30b1ed62f', '417365a8-31ea-5bc6-b24b-84b8ad8f9bfc', 'https://loremflickr.com/900/900/earbuds,wireless?lock=847', 4.40, 1876, TRUE, TRUE, TIMESTAMP '2026-01-04 10:28:00', TIMESTAMP '2026-01-04 10:28:00'),
  ('f4a53e54-9efb-570e-a0a9-59cc67112fce', 'NDK-RESON-WAL', 'nordkraft-resonance-bookshelf-speakers', 'Nordkraft Resonance Bookshelf Speakers', 'Two-way passive bookshelf pair in a real walnut veneer cabinet.', 'A 25mm soft-dome tweeter over a 130mm paper-cone woofer in a braced, ported cabinet. Nordkraft voices these flat rather than flattering, which makes them unforgiving of bad recordings and excellent with good ones. Sold as a matched pair; an amplifier is required.', 27499.00, NULL, 'INR', '7a83a44e-7ea9-588d-90a9-c6f30b1ed62f', '412add93-8c76-50ad-acd0-2ec76c6b3634', 'https://loremflickr.com/900/900/speakers,bookshelf?lock=824', 4.60, 412, FALSE, TRUE, TIMESTAMP '2026-01-05 10:35:00', TIMESTAMP '2026-01-05 10:35:00'),
  ('021f37b8-99e8-574a-8604-5c586e93b3e8', 'HAL-MON-PAIR', 'halcyon-studio-monitor-pair', 'Halcyon Studio Monitor Pair', 'Active nearfield monitors with room-correction trim controls.', 'Bi-amplified nearfields intended for a desk rather than a hall. Each cabinet carries its own 60W woofer amp and 30W tweeter amp, plus rear trim switches for desk-boundary and high-frequency compensation so an untreated room stops lying to you. Balanced XLR and TRS inputs.', 34999.00, 39999.00, 'INR', '7a83a44e-7ea9-588d-90a9-c6f30b1ed62f', 'cf291fcc-c7b1-530b-af85-9d825606e157', 'https://loremflickr.com/900/900/studio,monitor,speaker?lock=114', 4.80, 287, FALSE, TRUE, TIMESTAMP '2026-01-06 10:42:00', TIMESTAMP '2026-01-06 10:42:00'),
  ('2d4bc1ef-ba0d-514f-be5d-eac47ce54120', 'VNT-MER14-SLV', 'vantage-meridian-14-ultrabook', 'Vantage Meridian 14 Ultrabook', '14-inch magnesium ultrabook, 1.19 kg, 18-hour battery.', 'The Meridian 14 exists to be carried. A magnesium-alloy chassis keeps it at 1.19 kg without the flex that usually accompanies that number, and the 14-inch 2.8K display runs at 120Hz with a matte finish that survives working near a window. Two Thunderbolt 4 ports charge from either side.', 118999.00, 129999.00, 'INR', '06610ee3-a46b-5738-adfd-4ae2b5814604', 'bce54fa9-f9ed-57c2-9700-677ca6e97788', 'https://loremflickr.com/900/900/laptop,ultrabook?lock=551', 4.50, 934, TRUE, TRUE, TIMESTAMP '2026-01-07 10:49:00', TIMESTAMP '2026-01-07 10:49:00'),
  ('4a74101a-ff9e-57ba-abd3-b01b84e58e96', 'VNT-FRG16-GRY', 'vantage-forge-16-creator-laptop', 'Vantage Forge 16 Creator Laptop', '16-inch workstation with discrete graphics and a colour-accurate panel.', 'Forge 16 trades the ultrabook brief for sustained performance: a vapour-chamber cooling assembly that holds boost clocks through a long render, discrete workstation graphics, and a 16-inch panel covering 100% DCI-P3 and factory-calibrated to Delta-E under 2. Memory and storage are both user-accessible.', 189999.00, NULL, 'INR', '06610ee3-a46b-5738-adfd-4ae2b5814604', 'bce54fa9-f9ed-57c2-9700-677ca6e97788', 'https://loremflickr.com/900/900/laptop,workstation?lock=19', 4.60, 521, TRUE, TRUE, TIMESTAMP '2026-01-08 10:56:00', TIMESTAMP '2026-01-08 10:56:00'),
  ('33c6f1f3-4e76-54ad-95e9-38692dba8f00', 'CVX-APEX-KB', 'corvex-apex-mechanical-keyboard', 'Corvex Apex Mechanical Keyboard', '75% hot-swappable mechanical keyboard with a gasket mount.', 'A 75% layout that keeps the function row and arrow keys while dropping the numpad, gasket-mounted so the typing feel is cushioned rather than hollow. Hot-swap sockets take three- and five-pin switches without soldering, and the aluminium case has enough mass to stay put. Wired or 2.4GHz wireless.', 12499.00, 14999.00, 'INR', '06610ee3-a46b-5738-adfd-4ae2b5814604', 'eb1ffc4e-bf81-5499-814a-b15d2b125406', 'https://loremflickr.com/900/900/keyboard,mechanical?lock=575', 4.70, 1654, FALSE, TRUE, TIMESTAMP '2026-01-09 10:03:00', TIMESTAMP '2026-01-09 10:03:00'),
  ('6442b5d0-4b9a-5b67-be20-cb6eb3f3b81f', 'CVX-GLIDE-BLK', 'corvex-glide-wireless-mouse', 'Corvex Glide Wireless Mouse', 'Lightweight 58g wireless mouse with a 26K sensor.', 'Glide weighs 58 grams without resorting to a honeycomb shell, so it stays sealed against dust. The 26,000 DPI sensor tracks cleanly on everything short of glass, and a single AA-free internal cell runs about ninety hours between charges.', 4299.00, NULL, 'INR', '06610ee3-a46b-5738-adfd-4ae2b5814604', 'eb1ffc4e-bf81-5499-814a-b15d2b125406', 'https://loremflickr.com/900/900/mouse,computer?lock=705', 4.30, 2087, FALSE, TRUE, TIMESTAMP '2026-01-10 10:10:00', TIMESTAMP '2026-01-10 10:10:00'),
  ('03fdb501-0e02-5b63-bda8-a9e65a61dec4', 'LUM-CLR27-4K', 'lumen-clarity-27-4k-monitor', 'Lumen Clarity 27 4K Monitor', '27-inch 4K IPS display with USB-C power delivery.', 'A 27-inch 4K panel at the size where 4K stops being a spec and starts being useful: text renders at roughly 163 PPI without scaling artefacts. One USB-C cable carries video, data and 90W of charge to a laptop, and the stand adjusts through height, tilt, swivel and pivot rather than just tilt.', 42999.00, 49999.00, 'INR', '06610ee3-a46b-5738-adfd-4ae2b5814604', 'b38df3e2-81ab-58f4-9da4-95b566fa56c5', 'https://loremflickr.com/900/900/monitor,display?lock=647', 4.50, 743, TRUE, TRUE, TIMESTAMP '2026-01-11 10:17:00', TIMESTAMP '2026-01-11 10:17:00'),
  ('42427033-98d7-5020-a92f-49c6bdf9aa0c', 'NDK-VLT-2TB', 'nordkraft-vault-2tb-nvme-ssd', 'Nordkraft Vault 2TB NVMe SSD', 'PCIe 4.0 internal SSD with a five-year warranty.', 'A 2TB PCIe 4.0 drive rated at 7,300 MB/s sequential read, with a DRAM cache that keeps sustained writes from collapsing once the SLC buffer fills. The 8mm graphene heat spreader fits under most motherboard heatsinks and inside a PlayStation 5 expansion bay.', 15999.00, NULL, 'INR', '06610ee3-a46b-5738-adfd-4ae2b5814604', '412add93-8c76-50ad-acd0-2ec76c6b3634', 'https://loremflickr.com/900/900/ssd,storage?lock=249', 4.60, 1129, FALSE, TRUE, TIMESTAMP '2026-01-12 10:24:00', TIMESTAMP '2026-01-12 10:24:00'),
  ('b41c22a0-cbb0-5c00-9aa3-0a7925db296d', 'VNT-PLS5G-BLU', 'vantage-pulse-5g-smartphone', 'Vantage Pulse 5G Smartphone', '6.5-inch 5G phone with a 5000mAh cell and three-year updates.', 'Pulse covers the fundamentals properly rather than chasing a headline: a 6.5-inch 120Hz OLED, a 5000mAh battery that genuinely lasts a day of heavy use, and a commitment to three years of OS updates and four of security patches. The main camera uses a 50MP sensor with optical stabilisation.', 54999.00, 61999.00, 'INR', '4cdd788c-eb64-5767-b65f-9606f83b2bcb', 'bce54fa9-f9ed-57c2-9700-677ca6e97788', 'https://loremflickr.com/900/900/smartphone,phone?lock=495', 4.40, 3211, TRUE, TRUE, TIMESTAMP '2026-01-13 10:31:00', TIMESTAMP '2026-01-13 10:31:00'),
  ('54dcfc85-e51c-5515-a8ce-7f11e2e34d30', 'VNT-PLSPRO-BLK', 'vantage-pulse-pro-5g', 'Vantage Pulse Pro 5G', 'Flagship 6.8-inch phone with a periscope telephoto.', 'The Pro adds what the Pulse deliberately leaves out: a 5x periscope telephoto that keeps detail at distance, a brighter 6.8-inch panel that stays legible in direct sun at 2600 nits, and a titanium frame. Battery capacity is unchanged but charging rises to 80W.', 89999.00, NULL, 'INR', '4cdd788c-eb64-5767-b65f-9606f83b2bcb', 'bce54fa9-f9ed-57c2-9700-677ca6e97788', 'https://loremflickr.com/900/900/smartphone,flagship?lock=865', 4.60, 1487, FALSE, TRUE, TIMESTAMP '2026-01-14 10:38:00', TIMESTAMP '2026-01-14 10:38:00'),
  ('49e2b7fd-7d8f-534e-83ab-970e6b7e648d', 'LUM-SLT11', 'lumen-slate-11-tablet', 'Lumen Slate 11 Tablet', '11-inch tablet with stylus support and a laminated display.', 'Slate 11 uses a fully laminated 11-inch panel, so the stylus tip meets the mark rather than floating a millimetre above it. Sixteen hours of video playback, quad speakers that fire correctly in both orientations, and a magnetic edge that charges the stylus.', 38999.00, NULL, 'INR', '4cdd788c-eb64-5767-b65f-9606f83b2bcb', 'b38df3e2-81ab-58f4-9da4-95b566fa56c5', 'https://loremflickr.com/900/900/tablet?lock=703', 4.30, 664, FALSE, TRUE, TIMESTAMP '2026-01-15 10:45:00', TIMESTAMP '2026-01-15 10:45:00'),
  ('29dfc8bb-fbfe-5c2c-94c6-d7b007dfeab6', 'KST-PWR20K', 'kestrel-powercell-20k-power-bank', 'Kestrel PowerCell 20K Power Bank', '20,000mAh power bank with 65W USB-C output.', 'Enough capacity for four phone charges or one full laptop top-up, with 65W USB-C Power Delivery so it actually charges a laptop at a useful rate instead of merely slowing the drain. A small display shows remaining percentage rather than four ambiguous dots.', 3499.00, 4299.00, 'INR', '4cdd788c-eb64-5767-b65f-9606f83b2bcb', '9a164065-b228-5f1b-b13c-a17d29076747', 'https://loremflickr.com/900/900/powerbank,charger?lock=567', 4.50, 2934, FALSE, TRUE, TIMESTAMP '2026-01-16 10:52:00', TIMESTAMP '2026-01-16 10:52:00'),
  ('c92604ae-a1c3-5a0e-9850-aa313fa0b2ae', 'MRD-ARC-SLV', 'meridian-labs-arc-smartwatch', 'Meridian Labs Arc Smartwatch', 'Aluminium smartwatch with 7-day battery and built-in GPS.', 'Arc gets to seven days by refusing to run a phone on your wrist. What it does carry is accurate: dual-band GPS that holds a track between tall buildings, an optical heart-rate sensor validated against a chest strap, and sleep staging that does not invent deep sleep you did not have.', 24999.00, 28999.00, 'INR', '9d51aa3b-8168-5cd8-a37c-8df2604fe561', 'dc7b8f5b-458f-50fe-8bb3-883755145bff', 'https://loremflickr.com/900/900/smartwatch,watch?lock=504', 4.50, 1298, TRUE, TRUE, TIMESTAMP '2026-01-17 10:59:00', TIMESTAMP '2026-01-17 10:59:00'),
  ('e4dd746f-c87a-53ab-8b65-fa3f642c041a', 'MRD-TRC-BLK', 'meridian-labs-trace-fitness-band', 'Meridian Labs Trace Fitness Band', 'Slim fitness band with 14-day battery life.', 'Trace is deliberately narrow, so it disappears under a shirt cuff and stays comfortable overnight for sleep tracking. Fourteen days between charges, automatic recognition for six exercise types, and a screen bright enough to read outdoors.', 4999.00, NULL, 'INR', '9d51aa3b-8168-5cd8-a37c-8df2604fe561', 'dc7b8f5b-458f-50fe-8bb3-883755145bff', 'https://loremflickr.com/900/900/fitness,band,tracker?lock=542', 4.20, 3567, FALSE, TRUE, TIMESTAMP '2026-01-18 10:06:00', TIMESTAMP '2026-01-18 10:06:00'),
  ('132f0d76-19d4-5f94-9408-d8837e1106da', 'AUR-SPRNT-GRN', 'aurelia-sprint-sport-earbuds', 'Aurelia Sprint Sport Earbuds', 'Ear-hook sport earbuds rated IP67 with a secure fit.', 'Sprint uses a flexible over-ear hook rather than a wing tip, which is the difference between adjusting your earbuds mid-run and forgetting about them. IP67 survives being rinsed under a tap after a session, and an ambient mode lets traffic back in when you need it.', 5499.00, NULL, 'INR', '9d51aa3b-8168-5cd8-a37c-8df2604fe561', '417365a8-31ea-5bc6-b24b-84b8ad8f9bfc', 'https://loremflickr.com/900/900/earbuds,sport,running?lock=691', 4.30, 908, FALSE, TRUE, TIMESTAMP '2026-01-19 10:13:00', TIMESTAMP '2026-01-19 10:13:00'),
  ('b7e96173-0c4f-5771-95dd-a9129ef21d3e', 'HAL-EMBR-STL', 'halcyon-ember-espresso-machine', 'Halcyon Ember Espresso Machine', 'Dual-boiler espresso machine with PID temperature control.', 'A dual boiler means steaming milk and pulling a shot happen at once, at their own correct temperatures, instead of waiting for one vessel to change its mind. PID control holds brew temperature within half a degree, and the pressure gauge tells you what the puck is actually doing. Stainless steel throughout.', 46999.00, 54999.00, 'INR', '1b5a23ae-8705-55c1-a9a3-537afe033713', 'cf291fcc-c7b1-530b-af85-9d825606e157', 'https://loremflickr.com/900/900/espresso,coffee,machine?lock=661', 4.60, 476, TRUE, TRUE, TIMESTAMP '2026-01-20 10:20:00', TIMESTAMP '2026-01-20 10:20:00'),
  ('1049f1db-f249-551b-a0fe-838e88d5085f', 'HAL-BREW-KTL', 'halcyon-brew-precision-kettle', 'Halcyon Brew Precision Kettle', 'Gooseneck kettle with variable temperature and a hold timer.', 'The gooseneck spout gives a slow, steerable pour, which is most of what separates a good pour-over from a channelled one. Temperature is settable to the degree between 40 and 100 Celsius and can be held for an hour, so the second cup does not need reboiling.', 8999.00, NULL, 'INR', '1b5a23ae-8705-55c1-a9a3-537afe033713', 'cf291fcc-c7b1-530b-af85-9d825606e157', 'https://loremflickr.com/900/900/kettle,coffee,pourover?lock=875', 4.70, 1342, FALSE, TRUE, TIMESTAMP '2026-01-21 10:27:00', TIMESTAMP '2026-01-21 10:27:00'),
  ('c794c12d-44ee-5378-913c-a2012877c992', 'NDK-PURE-AIR', 'nordkraft-pure-air-purifier', 'Nordkraft Pure Air Purifier', 'HEPA-13 purifier rated for rooms up to 60 square metres.', 'A true HEPA-13 element behind a washable pre-filter and an activated carbon stage for odours and VOCs. Rated at 400 cubic metres per hour, which is enough to turn over a 60 square metre room roughly five times an hour. In night mode it runs at 24 dB.', 32999.00, 37999.00, 'INR', '1b5a23ae-8705-55c1-a9a3-537afe033713', '412add93-8c76-50ad-acd0-2ec76c6b3634', 'https://loremflickr.com/900/900/airpurifier,home?lock=152', 4.40, 623, FALSE, TRUE, TIMESTAMP '2026-01-22 10:34:00', TIMESTAMP '2026-01-22 10:34:00'),
  ('eeff95a6-fb55-5c76-ab0d-c9696b591527', 'KST-LUMDSK', 'kestrel-lumen-desk-lamp', 'Kestrel Lumen Desk Lamp', 'Asymmetric LED desk lamp with tunable colour temperature.', 'The asymmetric head throws light forward across a desk rather than down into your eyes, which is why it works in front of a monitor where a conventional lamp produces glare. Colour temperature runs from 2700K to 6000K and the whole range dims to 1% without flicker.', 6499.00, NULL, 'INR', '1b5a23ae-8705-55c1-a9a3-537afe033713', '9a164065-b228-5f1b-b13c-a17d29076747', 'https://loremflickr.com/900/900/desklamp,light?lock=582', 4.40, 851, FALSE, TRUE, TIMESTAMP '2026-01-23 10:41:00', TIMESTAMP '2026-01-23 10:41:00'),
  ('2a6528cc-98f5-5a4a-aebf-3d9e6b94a520', 'LUM-VSTA-BODY', 'lumen-vista-mirrorless-camera-body', 'Lumen Vista Mirrorless Camera Body', 'Full-frame 33MP mirrorless body with in-body stabilisation.', 'A 33MP full-frame sensor with five-axis in-body stabilisation rated at seven stops, which turns a lot of tripod situations back into handheld ones. Autofocus covers 94% of the frame with subject detection for people, animals and vehicles. Dual card slots, weather sealing, and a viewfinder that does not black out during bursts.', 134999.00, 149999.00, 'INR', '1a79b9fd-2436-5f30-8f4c-de6d3d65b383', 'b38df3e2-81ab-58f4-9da4-95b566fa56c5', 'https://loremflickr.com/900/900/camera,mirrorless?lock=531', 4.80, 392, TRUE, TRUE, TIMESTAMP '2026-01-24 10:48:00', TIMESTAMP '2026-01-24 10:48:00'),
  ('5fae9de6-5fd8-5c89-b9bb-a40924a143d1', 'LUM-VSTA-35', 'lumen-vista-35mm-f-1-8-lens', 'Lumen Vista 35mm f/1.8 Lens', 'Compact full-frame 35mm prime with weather sealing.', 'A 35mm that stays small enough to leave on the body, which is the whole argument for the focal length. Sharp across the frame from f/2, with a linear focus motor quiet enough for video and a manual focus ring that is actually usable. Weather-sealed to match the body.', 42999.00, NULL, 'INR', '1a79b9fd-2436-5f30-8f4c-de6d3d65b383', 'b38df3e2-81ab-58f4-9da4-95b566fa56c5', 'https://loremflickr.com/900/900/cameralens,photography?lock=506', 4.70, 268, FALSE, TRUE, TIMESTAMP '2026-01-25 10:55:00', TIMESTAMP '2026-01-25 10:55:00'),
  ('a9873b9f-ead9-57d9-b4e4-07b3be71de45', 'CVX-RIFT-CTL', 'corvex-rift-wireless-controller', 'Corvex Rift Wireless Controller', 'Wireless controller with hall-effect sticks and back paddles.', 'Hall-effect sticks use magnets instead of contact potentiometers, which is the fix for stick drift rather than a workaround for it. Four remappable back paddles, trigger stops for shooters, and a 40-hour battery. Connects over 2.4GHz, Bluetooth or USB-C.', 6999.00, 8499.00, 'INR', '8740d7f6-b451-5b59-b10b-124aa0e8a53d', 'eb1ffc4e-bf81-5499-814a-b15d2b125406', 'https://loremflickr.com/900/900/gamecontroller,gaming?lock=880', 4.50, 2456, FALSE, TRUE, TIMESTAMP '2026-01-26 10:02:00', TIMESTAMP '2026-01-26 10:02:00'),
  ('7a42ea07-0de4-583e-b059-a5e2349fd3c9', 'CVX-VCTR-HS', 'corvex-vector-gaming-headset', 'Corvex Vector Gaming Headset', 'Wireless gaming headset with a broadcast-grade boom microphone.', 'The detachable boom uses a cardioid capsule rather than the omnidirectional pinhole most headsets ship, so teammates hear you and not your keyboard. Fifty-millimetre drivers, a suspension headband that spreads weight across the crown, and simultaneous 2.4GHz and Bluetooth so game audio and a phone call can coexist.', 11999.00, NULL, 'INR', '8740d7f6-b451-5b59-b10b-124aa0e8a53d', 'eb1ffc4e-bf81-5499-814a-b15d2b125406', 'https://loremflickr.com/900/900/gamingheadset,headphones?lock=905', 4.40, 1105, FALSE, TRUE, TIMESTAMP '2026-01-27 10:09:00', TIMESTAMP '2026-01-27 10:09:00');
